from intervals import merge_intervals

def test_no_overlap():
    assert merge_intervals([[1, 2], [3, 4], [5, 6]]) == [[1, 2], [3, 4], [5, 6]]

def test_all_overlap():
    assert merge_intervals([[1, 4], [2, 5], [3, 6]]) == [[1, 6]]

def test_partial_overlap():
    assert merge_intervals([[1, 3], [2, 6], [8, 10], [15, 18]]) == [[1, 6], [8, 10], [15, 18]]

def test_empty():
    assert merge_intervals([]) == []

def test_single():
    assert merge_intervals([[1, 4]]) == [[1, 4]]

def test_unsorted_input():
    # 输入可能未排序，应正确处理
    assert merge_intervals([[8, 10], [1, 3], [2, 6]]) == [[1, 6], [8, 10]]

def test_contained_interval():
    # 一个区间完全包含在另一个里
    assert merge_intervals([[1, 10], [2, 5], [3, 4]]) == [[1, 10]]

def test_adjacent_not_overlapping():
    # 相邻但不重叠：[1,2] 和 [2,3] 视为重叠（端点相同）
    assert merge_intervals([[1, 2], [2, 3]]) == [[1, 3]]

def test_negative_numbers():
    assert merge_intervals([[-3, -1], [-2, 0], [1, 3]]) == [[-3, 0], [1, 3]]
